<?php
namespace App\Livewire\LMS\AssessmentScores;
use App\Models\{Assessment,AssessmentScore,GradingScale}; use App\Services\Results\SubjectResultCalculator; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Livewire\Attributes\Layout; use Livewire\Component;
#[Layout('layouts.lms')]
class Index extends Component { use AuthorizesRequests; public Assessment $assessment; public array $scores=[],$comments=[]; public function mount(Assessment $assessment):void{$this->authorize('update',$assessment);$this->assessment=$assessment;foreach($assessment->classSubject->schoolClass->enrollments()->with('student')->where('status','active')->get() as $enrollment){$record=$assessment->scores()->where('student_id',$enrollment->student_id)->first();$this->scores[$enrollment->student_id]=$record?->score??'';$this->comments[$enrollment->student_id]=$record?->comment??'';}} public function gradeFor(mixed $score):?string{if($score===''||$score===null)return null;$percentage=((float)$score/(float)$this->assessment->max_score)*100;return GradingScale::where('school_id',$this->assessment->classSubject->schoolClass->academicYear->school_id)->where('minimum','<=',$percentage)->where('maximum','>=',$percentage)->orderBy('sequence')->value('grade');} public function save():void{$this->authorize('update',$this->assessment);$this->validate(['scores.*'=>['nullable','numeric','min:0','max:'.$this->assessment->max_score],'comments.*'=>['nullable','string','max:1000']]);$calculator=app(SubjectResultCalculator::class);foreach($this->scores as $studentId=>$score){AssessmentScore::updateOrCreate(['assessment_id'=>$this->assessment->id,'student_id'=>$studentId],['score'=>$score===''?null:$score,'comment'=>$this->comments[$studentId]??null]);$calculator->calculate((int)$studentId,$this->assessment->class_subject_id,$this->assessment->term_id);}$this->dispatch('alert',type:'success',message:'Scores and subject results saved');} public function render(){return view('livewire.lms.assessment-scores.index',['students'=>$this->assessment->classSubject->schoolClass->enrollments()->with('student')->where('status','active')->get(),'scales'=>GradingScale::where('school_id',$this->assessment->classSubject->schoolClass->academicYear->school_id)->get()]);}}
